const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function setupProfiles({show,onSelect,getSelected}){
 let payload=null;
 async function load(){if(!payload){const r=await fetch('./profiles.json');if(!r.ok)throw Error('No se pudieron cargar las fichas');payload=await r.json()}return payload}
 function metric(m){const value=m.value==null?'Sin dato verificado':new Intl.NumberFormat('es',{maximumFractionDigits:m.unit==='personas'?0:2,notation:(m.unit==='USD'&&m.value>1e6)||m.unit==='personas'?'compact':'standard'}).format(m.value);return `<article class="fact"><span>${esc(m.label)}</span><b>${value} <small>${m.value==null?'':esc(m.unit)}</small></b><div class="factdate">${esc(m.period)} · <a href="${esc(m.url)}" target="_blank" rel="noopener">${esc(m.source)} ↗</a></div><p>${esc(m.note)}</p></article>`}
 function details(id){const p=payload.profiles.find(p=>p.id===id)||payload.profiles[0];const filled=Object.values(p.metrics).filter(m=>m.value!=null).length;
 show(`<div class="eyebrow">DOSSIER ESTRATÉGICO / DATOS PUBLICADOS</div><h2>${esc(p.name)}</h2><div class="dossiernav"><label for="dossierCountry">País / actor</label><select id="dossierCountry">${payload.profiles.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button id="showOnMap">Localizar en el mapa</button></div><p class="dossiernotice">Corte de consulta: <b>${payload.cutoff}</b> · ${filled}/9 indicadores disponibles.<br>Las fechas pertenecen a cada indicador. Actualización automática: <b>no conectada</b>.</p><h3>Economía y población</h3><div class="facts">${['population','gdp','income','growth','inflation','unemployment'].map(k=>metric(p.metrics[k])).join('')}</div><h3>Defensa · información agregada</h3><div class="facts">${['military','militaryShare','personnel'].map(k=>metric(p.metrics[k])).join('')}</div><p><a href="${p.nuclear.url}" target="_blank" rel="noopener">${esc(p.nuclear.text)} ↗</a> · ${p.nuclear.period}</p><h3>Vínculos institucionales verificados</h3><ul>${p.alliances.map(a=>`<li><a href="${a.url}" target="_blank" rel="noopener">${esc(a.text)} ↗</a></li>`).join('')}</ul><p class="factnote">Lista parcial: no representa todos los tratados o socios de este país.</p><section class="analyst"><div class="eyebrow">VALORACIÓN ANALÍTICA / NO ES UN HECHO MEDIDO</div><h3>Foco: ${esc(p.region)}</h3><p>${esc(p.assessment.focus)}</p><b>Factores que pueden contener la escalada</b><p>${esc(p.assessment.restraints)}</p><b>Relaciones a observar</b><div class="relations">${p.assessment.watch.map(id=>`<button data-dossier="${id}">${esc(payload.profiles.find(p=>p.id===id)?.name||id)}</button>`).join('')}</div></section><p class="factnote">${p.limitations.map(esc).join(' ')} El presupuesto militar no mide por sí solo la capacidad de combate. Estas fichas no alteran automáticamente la simulación.</p><button id="exportDossiers">Descargar las 20 fichas · JSON</button>`);
 document.getElementById('dossierCountry').onchange=e=>details(e.target.value);document.querySelectorAll('[data-dossier]').forEach(b=>b.onclick=()=>details(b.dataset.dossier));document.getElementById('showOnMap').onclick=()=>{const found=onSelect(p.id);if(!found){document.getElementById('showOnMap').textContent='Disponible en ficha; sin agente en el mapa base'}else document.getElementById('dialog').close()};document.getElementById('exportDossiers').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='civitas-20-paises-'+payload.cutoff+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
 }
 async function open(){try{await load();details(getSelected())}catch{show('<h2>Fichas no disponibles</h2><p>No se ha podido cargar el archivo de datos. Recarga la página y vuelve a intentarlo.</p>')}}
 document.getElementById('profiles').onclick=open;document.getElementById('openDossier').onclick=open;
}
